<?php
declare(strict_types=1);
namespace CoreviaOperationsTests;
require dirname(__DIR__,2).'/autoload.php';
use Corevia\Cli\DeploymentInspector;
use Corevia\Auth\SecretBox;
function check(bool $ok):void{if(!$ok){throw new \RuntimeException('Operations assertion failed.');}}
$root=dirname(__DIR__,2);$storage=sys_get_temp_dir().'/corevia-operations-'.bin2hex(random_bytes(6));mkdir($storage,0700);$names=['APP_ENV','APP_URL','APP_HTTPS','COREVIA_STORAGE','RUN_STORE','RUN_DB_CONNECTION','DB_CONNECTION','QUEUE_CONNECTION','AUTH_SHARED_KEY_PROVISIONED','COREVIA_BUILD_ARTIFACT','COREVIA_BUILD_KEY_FILE'];$old=[];foreach($names as $name){$old[$name]=getenv($name);}
try{
    putenv('COREVIA_STORAGE='.$storage);putenv('APP_ENV=production');putenv('APP_URL=https://app.example');putenv('APP_HTTPS=true');putenv('RUN_STORE=json');putenv('RUN_DB_CONNECTION');putenv('QUEUE_CONNECTION');putenv('DB_CONNECTION=local');putenv('AUTH_SHARED_KEY_PROVISIONED=false');
    $auth=['url'=>'https://app.example','driver'=>'json','delivery'=>'preview','mfa'=>true,'key_file'=>$storage.'/key','smtp'=>['password'=>'DO_NOT_PRINT_PRIVATE_FIXTURE']];$report=DeploymentInspector::inspect($root,$auth,[],true);$checks=array_column($report['checks'],'ok','id');check(!$report['ready']&&!$checks['shared_sessions']&&!$checks['shared_flow_store']&&!$checks['shared_mail_queue']&&!$checks['persisted_auth_key']&&!$checks['signed_sources']);check(!str_contains(json_encode($report),'DO_NOT_PRINT_PRIVATE_FIXTURE'));
    putenv('RUN_STORE=sql');putenv('DB_CONNECTION=mysql');putenv('AUTH_SHARED_KEY_PROVISIONED=true');$auth['driver']='sql';$auth['delivery']='sqlsmtp';file_put_contents($storage.'/key',random_bytes(32));chmod($storage.'/key',0600);$report=DeploymentInspector::inspect($root,$auth,['enabled'=>true,'base'=>'http://untrusted.example/v1','loopback'=>true,'model'=>'chosen'],true);$checks=array_column($report['checks'],'ok','id');check($checks['shared_sessions']&&$checks['shared_flow_store']&&$checks['shared_mail_queue']&&$checks['shared_key_provisioned']&&!$checks['ai_transport']&&!$report['external_services_checked']&&!$report['runtime_config_graph_checked']);
    putenv('DB_CONNECTION=sqlite');putenv('QUEUE_CONNECTION=sqlite');$checks=array_column(DeploymentInspector::inspect($root,$auth,[],true)['checks'],'ok','id');check(!$checks['shared_sessions']&&!$checks['shared_flow_store']&&!$checks['shared_mail_queue']&&!$checks['shared_work_queue']);putenv('QUEUE_CONNECTION');
    foreach(['https://user:secret@app.example','https://app.example/path','https://app.example?secret=value','https://app.example#fragment',"https://app.example\n"] as $url){$checks=array_column(DeploymentInspector::inspect($root,[...$auth,'url'=>$url],[],false)['checks'],'ok','id');check(!$checks['https_origin']);}
    foreach(['https://user:secret@model.example/v1','https://model.example/v1?key=private','ftp://127.0.0.1/v1','http://other.example/v1'] as $url){$checks=array_column(DeploymentInspector::inspect($root,$auth,['enabled'=>true,'model'=>'chosen','base'=>$url,'loopback'=>true],false)['checks'],'ok','id');check(!$checks['ai_transport']);}
    foreach(['https://model.example/v1','http://127.0.0.1:8111/v1','http://[::1]:8111/v1'] as $url){$checks=array_column(DeploymentInspector::inspect($root,$auth,['enabled'=>true,'model'=>'chosen','base'=>$url,'loopback'=>true],false)['checks'],'ok','id');check($checks['ai_transport']);}
    putenv('APP_HTTPS=false');$checks=array_column(DeploymentInspector::inspect($root,$auth,[],false)['checks'],'ok','id');check(!$checks['https_request_policy']);putenv('APP_HTTPS=true');
    $checks=array_column(DeploymentInspector::inspect($root,[...$auth,'delivery'=>'app.custom.delivery'],[],false)['checks'],'ok','id');check($checks['production_delivery']); // app:verify resolves the actual custom adapter.
    // Use a disposable document root, never place test secrets in the real public directory.
    $fixture=$storage.'/fixture';mkdir($fixture);mkdir($fixture.'/public');mkdir($fixture.'/config');mkdir($fixture.'/config/settings');foreach(['database','runtime','queue'] as $name){copy($root.'/config/settings/'.$name.'.php',$fixture.'/config/settings/'.$name.'.php');}
    file_put_contents($fixture.'/public/key',random_bytes(32));chmod($fixture.'/public/key',0600);file_put_contents($fixture.'/public/build.json','{}');chmod($fixture.'/public/build.json',0600);
    putenv('COREVIA_BUILD_ARTIFACT='.$fixture.'/public/build.json');putenv('COREVIA_BUILD_KEY_FILE='.$fixture.'/public/key');$checks=array_column(DeploymentInspector::inspect($fixture,[...$auth,'key_file'=>$fixture.'/public/key'],[],false)['checks'],'ok','id');check(!$checks['persisted_auth_key']&&!$checks['private_build_material']&&!$checks['signed_sources']);
    if(DIRECTORY_SEPARATOR!=='\\'){chmod($storage.'/key',0644);$checks=array_column(DeploymentInspector::inspect($root,$auth,[],false)['checks'],'ok','id');check(!$checks['persisted_auth_key']);chmod($storage.'/key',0600);chmod($storage,0755);$checks=array_column(DeploymentInspector::inspect($root,$auth,[],false)['checks'],'ok','id');check(!$checks['storage_permissions']);chmod($storage,0700);}
    if(function_exists('openssl_encrypt')){$key=SecretBox::fromFile($storage.'/key');$encrypted=$key->seal('fixture','bound-purpose');check(!file_exists($storage.'/key.lock'));check(SecretBox::fromFile($storage.'/key')->open($encrypted,'bound-purpose')==='fixture');}
    echo "PASS deployment multi-host/secret/transport checks, source evidence gate and provisioned-key loading\n";
}finally{foreach($old as $name=>$value){putenv($value===false?$name:$name.'='.$value);}if(isset($fixture)){foreach(glob($fixture.'/public/*') as $file){unlink($file);}foreach(glob($fixture.'/config/settings/*') as $file){unlink($file);}rmdir($fixture.'/public');rmdir($fixture.'/config/settings');rmdir($fixture.'/config');rmdir($fixture);}foreach(glob($storage.'/*') as $file){unlink($file);}rmdir($storage);}
